mutation discountCodeBasicCreate($basicCodeDiscount: DiscountCodeBasicInput!) {
  discountCodeBasicCreate(basicCodeDiscount: $basicCodeDiscount) {
    codeDiscountNode {
      id
      codeDiscount {
        ... on DiscountCodeBasic {
          title
          status
          startsAt
          endsAt
          usageLimit
          appliesOncePerCustomer
          context {
            ... on DiscountCustomers {
              customers {
                id
                displayName
              }
            }
          }
          codes(first: 1) {
            nodes {
              code
              asyncUsageCount
            }
          }
          customerGets {
            appliesOnOneTimePurchase
            value {
              ... on DiscountAmount {
                amount {
                  amount
                  currencyCode
                }
                appliesOnEachItem
              }
            }
            items {
              ... on AllDiscountItems {
                allItems
              }
              ... on DiscountCollections {
                collections(first: 10) {
                  nodes {
                    id
                    title
                  }
                }
              }
              ... on DiscountProducts {
                products(first: 10) {
                  nodes {
                    id
                    title
                  }
                }
                productVariants(first: 10) {
                  nodes {
                    id
                    title
                  }
                }
              }
            }
          }
        }
      }
    }
    userErrors {
      field
      code
      message
    }
  }
}
